1	package checkpointpolicy
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
8	)
9	
10	type Policy struct {
11		CheckpointVersion    string `json:"checkpoint_version,omitempty"`
12		CheckpointMinVersion string `json:"checkpoint_min_version,omitempty"`
13	}
14	
15	func DefaultPolicy() Policy {
16		return Policy{
17			CheckpointVersion:    checkpoint.CheckpointVersionBranchV1,
18			CheckpointMinVersion: checkpoint.CheckpointVersionBranchV1,
19		}
20	}
21	
22	func DefaultCheckpointVersion() string {
23		return checkpoint.CheckpointVersionBranchV1
24	}
25	
26	func Normalize(policy Policy) Policy {
27		if policy.CheckpointVersion == "" {
28			policy.CheckpointVersion = DefaultCheckpointVersion()
29		}
30		if policy.CheckpointMinVersion == "" {
31			policy.CheckpointMinVersion = checkpoint.CheckpointVersionBranchV1
32		}
33		return policy
34	}
35	
36	func ValidatePolicy(policy Policy) error {
37		policy = Normalize(policy)
38	
39		version, err := ParseFormat(policy.CheckpointVersion)
40		if err != nil {
41			return fmt.Errorf("checkpoint_version: %w", err)
42		}
43		if !CanWrite(version) {
44			return fmt.Errorf("checkpoint_version %q is not supported by this Entire CLI", policy.CheckpointVersion)
45		}
46	
47		minVersion, err := ParseFormat(policy.CheckpointMinVersion)
48		if err != nil {
49			return fmt.Errorf("checkpoint_min_version: %w", err)
50		}
51		if !CanRead(minVersion) {
52			return fmt.Errorf("checkpoint_min_version %q is not supported by this Entire CLI", policy.CheckpointMinVersion)
53		}
54		if Compare(minVersion, version) > 0 {
55			return fmt.Errorf("checkpoint_min_version %q is newer than checkpoint_version %q", policy.CheckpointMinVersion, policy.CheckpointVersion)
56		}
57	
58		return nil
59	}
60	
61	func RequiresUpgrade(policy Policy) bool {
62		policy = Normalize(policy)
63		minVersion, err := ParseFormat(policy.CheckpointMinVersion)
64		if err != nil {
65			return true
66		}
67		return !CanRead(minVersion)
68	}
69	
70	func UnsupportedWrite(policy Policy) bool {
71		policy = Normalize(policy)
72		version, err := ParseFormat(policy.CheckpointVersion)
73		if err != nil {
74			return true
75		}
76		return !CanWrite(version)
77	}
78	
79	func CanSatisfyPolicy(policy Policy) bool {
80		return !UnsupportedWrite(policy) && !RequiresUpgrade(policy)
81	}
82	
83	func UnsupportedPolicyMessage(policy Policy, updateCommand string) string {
84		if CanSatisfyPolicy(policy) {
85			return ""
86		}
87	
88		var b strings.Builder
89		fmt.Fprintf(&b, "[entire] This repository requires checkpoint support newer than this Entire CLI.\n[entire] Upgrade Entire, then rerun the command:\n[entire]   %s\n", updateCommand)
90		details := unsupportedPolicyDetails(policy)
91		if len(details) == 0 {
92			return b.String()
93		}
94		b.WriteString("[entire] Details:\n")
95		for _, detail := range details {
96			fmt.Fprintf(&b, "[entire]   %s\n", detail)
97		}
98		return b.String()
99	}
100	
101	func unsupportedPolicyDetails(policy Policy) []string {
102		policy = Normalize(policy)
103		var details []string
104	
105		version, err := ParseFormat(policy.CheckpointVersion)
106		if err != nil {
107			details = append(details, fmt.Sprintf("checkpoint_version %q is invalid: %v.", policy.CheckpointVersion, err))
108		} else if !CanWrite(version) {
109			details = append(details, fmt.Sprintf("checkpoint_version %q is not writable by this Entire CLI; this CLI defaults to %q.", policy.CheckpointVersion, DefaultCheckpointVersion()))
110		}
111	
112		minVersion, err := ParseFormat(policy.CheckpointMinVersion)
113		if err != nil {
114			details = append(details, fmt.Sprintf("checkpoint_min_version %q is invalid: %v.", policy.CheckpointMinVersion, err))
115		} else if !CanRead(minVersion) {
116			details = append(details, fmt.Sprintf("checkpoint_min_version %q is not readable by this Entire CLI; this CLI can read %q.", policy.CheckpointMinVersion, DefaultCheckpointVersion()))
117		}
118	
119		return details
120	}
