3	import (
4		"context"
5		"errors"
6		"fmt"
7	
8		"github.com/entireio/cli/cmd/entire/cli/checkpointpolicy"
9		"github.com/entireio/cli/cmd/entire/cli/gitrepo"
10		"github.com/spf13/cobra"
11	)
12	
13	type checkpointPolicyOptions struct {
14		version    string
15		minVersion string
16		force      bool
17	}
18	
19	const (
20		checkpointVersionFlag    = "checkpoint-version"
21		checkpointMinVersionFlag = "checkpoint-min-version"
22	)
23	
24	func newCheckpointPolicyCmd() *cobra.Command {
25		var opts checkpointPolicyOptions
26		cmd := &cobra.Command{
27			Use:   "policy",
28			Short: "Inspect and update checkpoint policy",
29			Long: `Inspect and update checkpoint policy.
30	
31	checkpoint_version selects the checkpoint metadata format used for new writes.
32	If no policy is configured, Entire uses the CLI default.
33	If another client configures a checkpoint_version this CLI cannot write,
34	commands that create checkpoint data fail until the CLI is upgraded. Other commands warn and
35	continue. Set checkpoint_version to "" to inherit the CLI default.
36	
37	checkpoint_min_version is an upgrade nudge and checkpoint-data write guard.
38	Clients that cannot read that version warn users to upgrade. Commands that
39	create checkpoint data fail until the CLI is upgraded. Other commands warn
40	and continue. Set checkpoint_min_version to "" to inherit the CLI default.
41	
42	Unsetting a field still uses the normal downgrade guard. If inheriting the
43	default would lower the field's effective version, pass --force to allow it.`,
44			Hidden: true,
45			Args:   cobra.NoArgs,
46			RunE: func(cmd *cobra.Command, _ []string) error {
47				return runCheckpointPolicy(cmd, opts)
48			},
49		}
50	
51		cmd.Flags().StringVar(&opts.version, checkpointVersionFlag, "", `Set checkpoint_version. Use "" to inherit the CLI default; --force may be required`)
52		cmd.Flags().StringVar(&opts.minVersion, checkpointMinVersionFlag, "", `Set checkpoint_min_version. Use "" to inherit the CLI default; --force may be required`)
53		cmd.Flags().BoolVar(&opts.force, "force", false, "Allow checkpoint policy version downgrades")
54		return cmd
55	}
56	
57	func runCheckpointPolicy(cmd *cobra.Command, opts checkpointPolicyOptions) error {
58		ctx := cmd.Context()
59		if err := ctx.Err(); err != nil {
60			return NewSilentError(err)
61		}
62		repo, err := gitrepo.OpenCurrent(ctx)
63		if err != nil {
64			return checkpointPolicyError("open repository", err)
65		}
66		defer repo.Close()
67	
68		target, err := checkpointpolicy.ResolveTarget(ctx)
69		if err != nil {
70			return checkpointPolicyError("resolve checkpoint policy remote", err)
71		}
72	
73		var state checkpointpolicy.State
74		checkpointVersionSet := cmd.Flags().Changed(checkpointVersionFlag)
75		checkpointMinVersionSet := cmd.Flags().Changed(checkpointMinVersionFlag)
76		if hasCheckpointPolicyUpdate(checkpointVersionSet, checkpointMinVersionSet) {
77			state, err = checkpointpolicy.Update(ctx, repo, target, checkpointpolicy.UpdateOptions{
78				CheckpointVersion:       opts.version,
79				CheckpointVersionSet:    checkpointVersionSet,
80				CheckpointMinVersion:    opts.minVersion,
81				CheckpointMinVersionSet: checkpointMinVersionSet,
82				Force:                   opts.force,
83			})
84			if err != nil {
85				return checkpointPolicyError("update checkpoint policy", err)
86			}
87			if err := checkpointpolicy.Push(ctx, target); err != nil {
88				return checkpointPolicyError("push checkpoint policy", err)
89			}
90			state.Source = checkpointpolicy.SourceRemote
91		} else {
92			state, err = checkpointpolicy.Sync(ctx, repo, target)
93			if err != nil {
94				return checkpointPolicyError("sync checkpoint policy", err)
95			}
96		}
97	
98		effectivePolicy := checkpointpolicy.Normalize(state.Policy)
99		fmt.Fprintf(cmd.OutOrStdout(), "checkpoint_version: %s\n", formatCheckpointVersionPolicyValue(state.Policy.CheckpointVersion, effectivePolicy.CheckpointVersion))
100		fmt.Fprintf(cmd.OutOrStdout(), "checkpoint_min_version: %s\n", formatCheckpointPolicyValue(state.Policy.CheckpointMinVersion, effectivePolicy.CheckpointMinVersion))
101		fmt.Fprintf(cmd.OutOrStdout(), "source: %s\n", state.Source)
102		return nil
103	}
104	
105	func hasCheckpointPolicyUpdate(checkpointVersionSet, checkpointMinVersionSet bool) bool {
106		return checkpointVersionSet || checkpointMinVersionSet
107	}
108	
109	func formatCheckpointPolicyValue(configured, effective string) string {
110		if configured == "" {
111			return effective + " (default)"
112		}
113		return configured
114	}
115	
116	func formatCheckpointVersionPolicyValue(configured, effective string) string {
117		if configured == "" {
118			return effective + " (default)"
119		}
120		if checkpointpolicy.UnsupportedWrite(checkpointpolicy.Policy{
121			CheckpointVersion:    configured,
122			CheckpointMinVersion: checkpointpolicy.DefaultCheckpointVersion(),
123		}) {
124			return configured + " (unsupported)"
125		}
126		return configured
127	}
128	
129	func checkpointPolicyError(message string, err error) error {
130		wrapped := fmt.Errorf("%s: %w", message, err)
131		if errors.Is(wrapped, context.Canceled) {
132			return NewSilentError(wrapped)
133		}
134		return wrapped
135	}
