15	var errUnsupportedCheckpointPolicy = errors.New("checkpoint policy cannot be satisfied by this Entire CLI")
16	var errUnreadableCheckpointPolicy = errors.New("checkpoint policy could not be read")
17	
18	func checkpointVersionForNewCheckpoint(ctx context.Context, repo *git.Repository) (string, error) {
19		policy, err := checkpointPolicyForCheckpointData(ctx, repo)
20		if err != nil {
21			return "", err
22		}
23		if !checkpointpolicy.CanSatisfyPolicy(policy) {
24			return "", unsupportedCheckpointPolicyError(policy)
25		}
26		return checkpointpolicy.Normalize(policy).CheckpointVersion, nil
27	}
28	
29	func ensureCheckpointPolicyAllowsCheckpointData(ctx context.Context, repo *git.Repository) error {
30		policy, err := checkpointPolicyForCheckpointData(ctx, repo)
31		if err != nil {
32			return err
33		}
34		if checkpointpolicy.CanSatisfyPolicy(policy) {
35			return nil
36		}
37		return unsupportedCheckpointPolicyError(policy)
38	}
39	
40	func checkpointPolicyForCheckpointData(ctx context.Context, repo *git.Repository) (checkpointpolicy.Policy, error) {
41		state, err := checkpointpolicy.ReadLocal(ctx, repo)
42		if err != nil {
43			return checkpointpolicy.Policy{}, unreadableCheckpointPolicyError(err)
44		}
45		return state.Policy, nil
46	}
47	
48	func unsupportedCheckpointPolicyError(policy checkpointpolicy.Policy) error {
49		message := strings.TrimSpace(checkpointpolicy.UnsupportedPolicyMessage(
50			policy,
51			versioncheck.UpdateCommandForCurrentBinary(versioninfo.Version),
52		))
53		return fmt.Errorf("%w:\n%s", errUnsupportedCheckpointPolicy, message)
54	}
55	
56	func unreadableCheckpointPolicyError(err error) error {
57		return fmt.Errorf("%w: %w", errUnreadableCheckpointPolicy, err)
58	}
