16	
17	func readLocalCheckpointPolicy(ctx context.Context, repo *git.Repository) (checkpointpolicy.Policy, error) {
18		state, err := checkpointpolicy.ReadLocal(ctx, repo)
19		if err != nil {
20			logging.Warn(ctx, "checkpoint policy read failed",
21				slog.String("error", err.Error()),
22			)
23			return checkpointpolicy.Policy{}, err
24		}
25		return state.Policy, nil
26	}
27	
28	func checkpointPolicyAllowsGitHook(ctx context.Context, repo *git.Repository) bool {
29		policy, err := readLocalCheckpointPolicy(ctx, repo)
30		if err != nil {
31			warnOrLogCheckpointPolicyReadFailure(ctx, err)
32			return false
33		}
34		if checkpointpolicy.CanSatisfyPolicy(policy) {
35			return true
36		}
37		warnOrLogCheckpointPolicyUpgrade(ctx, policy)
38		return false
39	}
40	
41	func syncCheckpointPolicyForPrePush(ctx context.Context, repo *git.Repository, ps pushSettings) {
42		dir, err := paths.WorktreeRoot(ctx)
43		if err != nil {
44			logging.Warn(ctx, "checkpoint policy pre-push: failed to resolve worktree root; allowing checkpoint push",
45				slog.String("error", err.Error()),
46			)
47			return
48		}
49		target := checkpointpolicy.Target{Remote: ps.pushTarget(), Dir: dir}
50		state, err := checkpointpolicy.Sync(ctx, repo, target)
51		if err != nil {
52			warnOrLogCheckpointPolicySyncFailure(ctx, err)
53			return
54		}
55		if state.Source == checkpointpolicy.SourceLocalDiverged {
56			warnOrLogCheckpointPolicyDiverged(ctx, state)
57			return
58		}
59	}
60	
61	func warnOrLogCheckpointPolicyReadFailure(ctx context.Context, err error) {
62		if interactive.CanPromptInteractively() {
63			fmt.Fprintf(stderrWriter, "[entire] Could not read checkpoint policy; skipping Entire checkpoint work: %v\n", err)
64			return
65		}
66		logging.Warn(ctx, "checkpoint policy read failed; skipping checkpoint work",
67			slog.String("error", err.Error()),
68		)
69	}
70	
71	func warnOrLogCheckpointPolicySyncFailure(ctx context.Context, err error) {
72		if interactive.CanPromptInteractively() {
73			fmt.Fprintf(stderrWriter, "[entire] Could not refresh checkpoint policy: %v\n", err)
74			return
75		}
76		logging.Warn(ctx, "checkpoint policy sync failed",
77			slog.String("error", err.Error()),
78		)
79	}
80	
81	func warnOrLogCheckpointPolicyDiverged(ctx context.Context, state checkpointpolicy.State) {
82		if interactive.CanPromptInteractively() {
83			fmt.Fprintf(
84				stderrWriter,
85				"[entire] Could not reconcile checkpoint policy: local checkpoint policy %s diverges from remote %s\n",
86				state.Hash,
87				state.RemoteHash,
88			)
89			return
90		}
91		logging.Warn(ctx, "checkpoint policy diverged; allowing checkpoint push",
92			slog.String("local_hash", state.Hash.String()),
93			slog.String("remote_hash", state.RemoteHash.String()),
94		)
95	}
96	
97	func warnIfCheckpointPolicyNeedsUpgrade(ctx context.Context, policy checkpointpolicy.Policy) {
98		if checkpointpolicy.CanSatisfyPolicy(policy) {
99			return
100		}
101		warnOrLogCheckpointPolicyUpgrade(ctx, policy)
102	}
103	
104	func warnOrLogCheckpointPolicyUpgrade(ctx context.Context, policy checkpointpolicy.Policy) {
105		warning := checkpointpolicy.UnsupportedPolicyMessage(policy, versioncheck.UpdateCommandForCurrentBinary(versioninfo.Version))
106		if interactive.CanPromptInteractively() {
107			fmt.Fprint(stderrWriter, warning)
108			return
109		}
110		logging.Warn(ctx, "checkpoint policy requires newer CLI",
111			slog.String("checkpoint_version", policy.CheckpointVersion),
112			slog.String("checkpoint_min_version", policy.CheckpointMinVersion),
113		)
114	}
