14	func ShouldCheckCheckpointPolicyWarning(cmd *cobra.Command) bool {
15		if cmd == nil {
16			return false
17		}
18		for c := cmd; c != nil; c = c.Parent() {
19			if isCheckpointPolicyWarningExcludedCommand(c.Name()) {
20				return false
21			}
22		}
23		return true
24	}
25	
26	func isCheckpointPolicyWarningExcludedCommand(name string) bool {
27		switch name {
28		case "hooks", "__send_analytics", "curl-bash-post-install":
29			return true
30		default:
31			return false
32		}
33	}
34	
35	func WarnCheckpointPolicyIfNeeded(ctx context.Context, w io.Writer, currentVersion string) {
36		repo, err := gitrepo.OpenCurrent(ctx)
37		if err != nil {
38			return
39		}
40		defer repo.Close()
41	
42		state, err := checkpointpolicy.ReadLocal(ctx, repo)
43		if err != nil {
44			return
45		}
46		if checkpointpolicy.CanSatisfyPolicy(state.Policy) {
47			return
48		}
49	
50		fmt.Fprint(w, checkpointpolicy.UnsupportedPolicyMessage(
51			state.Policy,
52			versioncheck.UpdateCommandForCurrentBinary(currentVersion),
53		))
54	}
