40	func ReadLocal(ctx context.Context, repo *git.Repository) (State, error) {
41		ref, err := repo.Reference(RefName, true)
42		if err != nil {
43			if errors.Is(err, plumbing.ErrReferenceNotFound) {
44				return State{Source: SourceDefaults}, nil
