59	func WriteLocal(ctx context.Context, repo *git.Repository, parent plumbing.Hash, policy Policy) (plumbing.Hash, error) {
60		data, err := jsonutil.MarshalIndentWithNewline(policy, "", "  ")
61		if err != nil {
62			return plumbing.ZeroHash, fmt.Errorf("marshal checkpoint policy: %w", err)
63		}
64		blobHash, err := checkpoint.CreateBlobFromContent(repo, data)
65		if err != nil {
66			return plumbing.ZeroHash, fmt.Errorf("create checkpoint policy blob: %w", err)
67		}
68		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, map[string]object.TreeEntry{
69			PolicyFileName: {Name: PolicyFileName, Mode: filemode.Regular, Hash: blobHash},
70		})
71		if err != nil {
72			return plumbing.ZeroHash, fmt.Errorf("build checkpoint policy tree: %w", err)
73		}
74		authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(repo)
75		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, parent, "Update checkpoint policy", authorName, authorEmail)
76		if err != nil {
77			return plumbing.ZeroHash, fmt.Errorf("create checkpoint policy commit: %w", err)
78		}
79		if err := SetRef(repo, RefName, commitHash); err != nil {
80			return plumbing.ZeroHash, err
81		}
82		return commitHash, nil
83	}
