92	func readFromHash(ctx context.Context, repo *git.Repository, hash plumbing.Hash, source Source) (State, error) {
93		if err := ctx.Err(); err != nil {
94			return State{}, fmt.Errorf("read checkpoint policy: %w", err)
95		}
96		commit, err := repo.CommitObject(hash)
97		if err != nil {
98			return State{}, fmt.Errorf("read checkpoint policy commit: %w", err)
99		}
100		tree, err := commit.Tree()
101		if err != nil {
102			return State{}, fmt.Errorf("read checkpoint policy tree: %w", err)
103		}
104		file, err := tree.File(PolicyFileName)
105		if err != nil {
106			return State{}, fmt.Errorf("read %s: %w", PolicyFileName, err)
107		}
108		if file.Size > maxPolicyFileBytes {
109			return State{}, fmt.Errorf("parse %s: file exceeds %d bytes", PolicyFileName, maxPolicyFileBytes)
110		}
111		reader, err := file.Reader()
112		if err != nil {
113			return State{}, fmt.Errorf("read %s contents: %w", PolicyFileName, err)
114		}
115		defer reader.Close()
116	
117		var policy Policy
118		decoder := json.NewDecoder(io.LimitReader(reader, maxPolicyFileBytes))
119		if err := decoder.Decode(&policy); err != nil {
120			return State{}, fmt.Errorf("parse %s: %w", PolicyFileName, err)
121		}
122		var trailingValue json.RawMessage
123		if err := decoder.Decode(&trailingValue); !errors.Is(err, io.EOF) {
124			if err == nil {
125				return State{}, fmt.Errorf("parse %s: multiple JSON values", PolicyFileName)
126			}
127			return State{}, fmt.Errorf("parse %s: %w", PolicyFileName, err)
128		}
129		return State{Policy: policy, Source: source, Hash: hash}, nil
130	}
